];
const rs = await Promise.all(paths.map(path => tools.exec_command({cmd:`sed -n '1,260p' ${path}`,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:10000,max_output_tokens:12000})));
