const cmds = [
  'printf "ENV\\n"; env | rg "^(ARCHON_HORIZON|HORIZON_BIN|HORIZON_GIT)"',
  '"$HORIZON_BIN" ps',
  '"$HORIZON_BIN" usage --json',
  '"$HORIZON_BIN" inbox list --mine --status open --kind protection --json',
  '"$HORIZON_BIN" inbox list --mine --unread --kind conversation --json',
  '"$HORIZON_BIN" inbox list --mine --status open --kind issue --json',
  '"$HORIZON_BIN" roadmap list --focus AJCR.review-plan.p7-galois-descent --json',
  '"$HORIZON_BIN" task list --json'
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:16000})));
rs.forEach((r,i)=>text(`--- ${i+1} ---\n${r.output}`));

const cmds = [
  '"$HORIZON_BIN" inbox list --mine --status open --kind protection --json | jq \'{attention: .attention.required_protections, items: [.items[] | {id, title, project:.scope.project, projects:.scope.projects, updated_at}] , warnings}\'',
  '"$HORIZON_BIN" inbox list --mine --status open --kind conversation --json | jq \'{attention: .attention.unread_conversations, items: [.items[] | {id, title, project:.scope.project, audience, owner_task:.owner_task, updated_at}], warnings}\'',
  '"$HORIZON_BIN" inbox list --mine --status open --kind issue --json | jq \'{items: [.items[] | select((.projects|join(","))|test("Algebraic-Jacobian-Challenge")) | {id,title,projects,status,owner_task,updated_at}], warnings}\'',
  '"$HORIZON_BIN" task list --json | jq \'{warnings, tasks: [.tasks[] | select((.projects|join(","))|test("Algebraic-Jacobian-Challenge")) | {id,title,status,projects,roadmap_refs,updated_at}]}\'',
  '"$HORIZON_BIN" roadmap list --focus AJCR.review-plan.p7-galois-descent --json | jq \'{warnings, root: .roadmap, items: (.items // []) | map({id,title,status,owner,parent,milestone,children})}\''
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:10000})));
rs.forEach((r,i)=>text(`--- ${i+1} ---\n${r.output}`));

const cmds = [
  '"$HORIZON_BIN" roadmap list --focus AJCR.review-plan --max-depth 2',
  '"$HORIZON_BIN" task list --status running --json | jq \'{warnings, tasks: [.tasks[] | {id,title,status,projects,roadmap_refs}]}\'',
  '"$HORIZON_BIN" task show ajcr-reviewer-full --json | jq \'{id,title,status,projects,roadmap_refs,comments,history,warnings}\'',
  '"$HORIZON_BIN" ps --json',
  '"$HORIZON_BIN" inbox list --mine --status open --json | jq \'{attention, warnings, counts: ([.items[] | .kind] | group_by(.) | map({kind:.[0],count:length}))}\'',
  '"$HORIZON_BIN" --help | sed -n '1,220p'"
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:12000})));
rs.forEach((r,i)=>text(`--- ${i+1} ---\n${r.output}`));

const cmds = [
  `"$HORIZON_BIN" roadmap list --focus AJCR.review-plan --max-depth 2`,
  `"$HORIZON_BIN" task list --status running --json | jq '{warnings, tasks: [.tasks[] | {id,title,status,projects,roadmap_refs}]}'`,
  `"$HORIZON_BIN" task show ajcr-reviewer-full --json | jq '{id,title,status,projects,roadmap_refs,comments,history,warnings}'`,
  `"$HORIZON_BIN" ps --json`,
  `"$HORIZON_BIN" inbox list --mine --status open --json | jq '{attention, warnings, counts: ([.items[] | .kind] | group_by(.) | map({kind:.[0],count:length}))}'`,
  `"$HORIZON_BIN" --help | sed -n '1,220p'`
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:12000})));
rs.forEach((r,i)=>text(`--- ${i+1} ---\n${r.output}`));

const cmds = [
  `"$HORIZON_BIN" inbox list --mine --status open --kind conversation --json | jq -r '.items[]? | "\\(.id)\\t\\(.audience)\\t\\(.status)\\t" + ((.body // "") | split("\\n")[0])'`,
  `"$HORIZON_BIN" inbox list --mine --status open --kind issue --json | jq -r '.items[]? | "\\(.id)\\t\\(.audience)\\t\\(.status)\\t\\((.scope.projects // [])|join(","))\\t" + ((.body // "") | split("\\n")[0])'`,
  `for id in I-1222 I-1985 I-1986 I-1913 I-2008 I-2009 I-1993 I-1927; do echo "=== $id ==="; "$HORIZON_BIN" inbox show "$id" --no-mark-read --json | jq -r '.item // . | {id,kind,status,audience,scope,body,comments}'; done`,
  `"$HORIZON_BIN" task list -h`,
  `"$HORIZON_BIN" roadmap list --focus AJCR.review-plan.p7-galois-descent --json | jq '.warnings, .items[]? | {id,status,parent,owner}'`
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:16000})));
rs.forEach((r,i)=>text(`--- ${i+1} ---\n${r.output}`));

const cmds = [
  `"$HORIZON_BIN" roadmap list --json | jq 'type, (if type=="array" then length else ((.items // .roadmap // [])|length) end), (if type=="array" then (group_by(.status)|map({status:.[0].status,n:length})) else ((.items // .roadmap // [])|group_by(.status)|map({status:.[0].status,n:length})) end)'`,
  `"$HORIZON_BIN" task list --json | jq '(.tasks // .items // []) | {total:length, by_status:(group_by(.status)|map({status:.[0].status,n:length})), running:[.[]|select(.status=="running")|{id,title,projects}]}'`,
  `for id in I-1975 I-1986 I-1913 I-1920 I-1646 I-1922 I-1987; do echo "=== $id ==="; "$HORIZON_BIN" inbox show "$id" --no-mark-read --json 2>/dev/null | jq -r '(.item // .) | [.id,.kind,.status,.audience,((.body//"")|split("\\n\\n")[0])] | @tsv'; done`,
  `"$HORIZON_BIN" inbox list --mine --status open --json | jq '(.items // []) | {total:length,by_kind:(group_by(.kind)|map({kind:.[0].kind,n:length}))}'`
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:10000})));
rs.forEach((r,i)=>text(`--- ${i+1} ---\n${r.output}`));

